const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)];
const history=$('#history'),start=$('#start'),pause=$('#pause'),failure=$('#failure'),canvas=$('#canvas'),wrap=$('.canvas-wrap'),swarm=$('#swarm');
const blueprint=$('#page-blueprint').content;
[...blueprint.querySelectorAll('*')].forEach((el,i)=>el.dataset.buildId=String(i));
const names={logo:'브랜드 로고','nav-links':'내비게이션',eyebrow:'히어로 라벨','hero-title':'히어로 제목','hero-body':'히어로 설명',cta:'CTA',media:'키비주얼','section-title':'콘텐츠 제목','card-1':'카드 1','card-2':'카드 2','card-3':'카드 3','footer-title':'마무리 제목','footer-brand':'푸터 브랜드'};
let mode=document.body.dataset.initialMode==='component'?'component':'section',tasks=[],phase='wireframe',running=false,paused=false,failed=false,last=0,elapsed=0,frame=0;
const reduced=matchMedia('(prefers-reduced-motion: reduce)');
const colors=['#246bce','#9a4fc4','#c4692f','#298367','#c24c77','#597bb5','#aa8135','#467e96','#895b93','#538342','#bf6656','#6669ae'];
const cursors=colors.map((color,i)=>{const el=document.createElement('div');el.className='swarm-cursor';el.style.setProperty('--cursor-color',color);el.innerHTML='<svg viewBox="0 0 24 28" width="21" height="25"><path d="M2 2L21 15L12 17L8 25Z" fill="currentColor" stroke="white" stroke-width="1.5" stroke-linejoin="round"/></svg><span></span>';swarm.append(el);return {el,x:0,y:0,initialized:false,index:i};});
function prepareEditor(task){
 if(mode!=='component')return;
 task.box=document.createElement('div');task.box.className='edit-box';task.box.style.setProperty('--edit-color',colors[tasks.indexOf(task)%colors.length]);
 const caption=document.createElement('span');caption.className='edit-caption';caption.textContent=task.name+(task.media?' · 이미지':' · 텍스트 입력');
 task.box.append(caption);for(let i=0;i<4;i++){const handle=document.createElement('i');handle.className='edit-handle handle-'+i;task.box.append(handle);}
 task.caret=document.createElement('i');task.caret.className='edit-caret';task.box.append(task.caret);swarm.append(task.box);
 if(phase==='wireframe'&&!task.media){task.el.replaceChildren(...[...task.source.childNodes].map(node=>node.cloneNode(true)));task.typing=[];
 const walker=document.createTreeWalker(task.el,NodeFilter.SHOW_TEXT),nodes=[];while(walker.nextNode())if(walker.currentNode.textContent.trim())nodes.push(walker.currentNode);
 for(const node of nodes){const full=node.textContent,holder=document.createElement('span'),ink=document.createElement('span'),ghost=document.createElement('span');holder.className='typing-run';ink.className='typed-text';ghost.className='untyped-text';ghost.setAttribute('aria-hidden','true');ghost.textContent=full;holder.append(ink,ghost);node.replaceWith(holder);task.typing.push({full,ink,ghost});}
 task.totalLetters=task.typing.reduce((sum,item)=>sum+Array.from(item.full).length,0);task.el.classList.add('typing-preview');}
}
function typeText(task){if(!task.typing)return;let budget=reduced.matches?task.totalLetters:Math.floor(task.totalLetters*Math.max(0,Math.min(1,(task.spent/task.duration-.12)/.72)));task.lastInk=null;
 for(const item of task.typing){const chars=Array.from(item.full),count=Math.min(chars.length,budget);item.ink.textContent=chars.slice(0,count).join('');item.ghost.textContent=chars.slice(count).join('');if(count)task.lastInk=item.ink;budget=Math.max(0,budget-count);}}
function editorGeometry(task){if(!task.box)return;const rect=task.el.getBoundingClientRect(),r=wrap.getBoundingClientRect();task.box.hidden=rect.bottom<r.top||rect.top>r.bottom;task.box.style.transform=`translate(${rect.left-r.left+wrap.scrollLeft-3}px,${rect.top-r.top+wrap.scrollTop-3}px)`;task.box.style.width=`${rect.width+6}px`;task.box.style.height=`${rect.height+6}px`;
 task.caret.hidden=task.media||!task.typing;if(task.lastInk){const range=document.createRange();range.selectNodeContents(task.lastInk);const lines=[...range.getClientRects()],last=lines.at(-1);if(last){task.caret.style.left=`${last.right-rect.left+3}px`;task.caret.style.top=`${last.top-rect.top+3}px`;task.caret.style.height=`${Math.max(12,last.height)}px`;task.pen={x:last.right,y:last.bottom};}}else task.pen={x:rect.left+8,y:rect.top+18};}
function closeEditor(task){task.box?.remove();task.el?.classList.remove('typing-preview');}
function message(text,meta='',user=false){const pinned=history.scrollHeight-history.scrollTop-history.clientHeight<40,row=document.createElement('div');row.className='message'+(user?' user':'');if(meta){const label=document.createElement('span');label.className='meta';label.textContent=meta;row.append(label);}const body=document.createElement('span');body.className='body';body.textContent=text;row.append(body);history.append(row);if(pinned)history.scrollTop=history.scrollHeight;return row;}
function designTasks(){return mode==='section'?$$('[data-region]').map((el,i)=>({el,name:['내비게이션','히어로','콘텐츠 섹션','마무리 영역'][i],media:el.dataset.region==='hero',duration:4400+i*400,state:'pending',spent:0})):$$('[data-component]').map((el,i)=>({el,name:names[el.dataset.component],media:el.dataset.component==='media',duration:3600+(i%5)*550,state:'pending',spent:0}));}
function wireTasks(){const selector=mode==='section'?'[data-region]':'[data-component]';return [...blueprint.querySelectorAll(selector)].map((source,i)=>({source,el:null,media:source.dataset.component==='media',name:mode==='section'?['내비게이션','히어로','콘텐츠 섹션','마무리 영역'][i]:names[source.dataset.component],duration:1800+(i%4)*350,state:'pending',spent:0}));}
function mount(source){if(!source||source===blueprint)return canvas;const existing=canvas.querySelector(`[data-build-id="${source.dataset.buildId}"]`);if(existing)return existing;const parent=source.parentElement?mount(source.parentElement):canvas,el=source.cloneNode(false);if(el.dataset.region)el.dataset.state='pending';if(el.dataset.component)el.dataset.render='pending';parent.append(el);return el;}
function progress(){const done=tasks.filter(t=>t.state==='ready').length;canvas.dataset.phase=phase;$('#progress-fill').style.width=`${done/tasks.length*100}%`;$('.progress').setAttribute('aria-valuemax',tasks.length);$('.progress').setAttribute('aria-valuenow',done);$('#count').textContent=`${phase==='wireframe'?'와이어프레임':'디자인'} · ${done} / ${tasks.length} ${mode==='section'?'섹션':'컴포넌트'} 완료`;}
function prepareMedia(task){if(phase!=='design'||!task.media)return;task.decodeState='pending';Promise.all([...canvas.querySelectorAll('#hero-art img')].map(img=>img.decode())).then(()=>{task.decodeState='ready';},()=>{task.decodeState='failed';});}
function reveal(task){task.el.dataset[mode==='section'?'state':'render']='ready';if(!task.media){task.el.classList.add('reveal');task.el.addEventListener('animationend',()=>task.el.classList.remove('reveal'),{once:true});}if(task.media){$('#hero-art').dataset.ready='true';$('#media-label').textContent='키비주얼 완료';}}
function activate(){const capacity=mode==='section'?1:12;for(const task of tasks){if(tasks.filter(t=>t.state==='working').length>=capacity)break;if(task.state!=='pending')continue;task.state='working';if(phase==='wireframe'){task.el=mount(task.source);task.el.dataset.build='working';task.el.classList.add('building-block');}task.el.dataset[mode==='section'?'state':'render']='working';task.row=message(`${task.name} ${phase==='wireframe'?'와이어프레임을 생성':'디자인을 구성'}하고 있습니다.`,`${mode==='section'?'섹션':'컴포넌트'} ${tasks.indexOf(task)+1} / ${tasks.length} · 데모 생성 중`);task.row.classList.add('active');prepareEditor(task);prepareMedia(task);canvas.dispatchEvent(new CustomEvent('demo:taskstart',{detail:{el:task.el,name:task.name,phase}}));if(phase==='design'&&task.media&&$('#media-label'))$('#media-label').textContent='키비주얼 준비 중';}const active=tasks.filter(t=>t.state==='working');$('#status').textContent=`${phase==='wireframe'?'① 와이어프레임 생성':'② 디자인 생성'} · ${active.length}개 작업 · 커서 12개`;}
function stopFrame(){cancelAnimationFrame(frame);frame=0;swarm.hidden=true;}
function moveCursors(dt){tasks.filter(t=>t.state==='working').forEach(editorGeometry);const active=tasks.filter(t=>t.state==='working'),r=wrap.getBoundingClientRect();for(const cursor of cursors){const target=active[mode==='section'?0:cursor.index%active.length];if(!target)continue;const rect=target.el.getBoundingClientRect(),phase=(reduced.matches?0:elapsed/1300)+cursor.index*1.256;
 const left=Math.max(r.left+10,rect.left),right=Math.min(r.right-90,rect.right-Math.min(10,rect.width*.1)),top=Math.max(r.top+12,rect.top+Math.min(4,rect.height*.1)),bottom=Math.min(r.bottom-35,rect.bottom-Math.min(4,rect.height*.1));
 let tx=(right>=left?left+(right-left)*(.5+.4*Math.sin(phase)):r.left+12+(cursor.index%3)*45)-r.left+wrap.scrollLeft;
 let ty=(bottom>=top?top+(bottom-top)*(.5+.36*Math.cos(phase*.8)):rect.top>=r.bottom?r.bottom-45:r.top+20)-r.top+wrap.scrollTop;
 if(mode==='component'&&target.typing&&target.pen&&!reduced.matches){tx=Math.max(12,Math.min(r.width-100,target.pen.x-r.left+wrap.scrollLeft+8));ty=Math.max(wrap.scrollTop+12,Math.min(wrap.scrollTop+r.height-40,target.pen.y-r.top+wrap.scrollTop+5));}
 if(!cursor.initialized||reduced.matches){cursor.x=tx;cursor.y=ty;cursor.initialized=true;}else{const a=1-Math.exp(-dt/160);cursor.x+=(tx-cursor.x)*a;cursor.y+=(ty-cursor.y)*a;}
 cursor.el.style.transform=`translate3d(${cursor.x}px,${cursor.y}px,0)`;cursor.el.querySelector('span').textContent=`${cursor.index+1} · ${target.name}`;}}
function tick(now){if(!running||paused)return;const dt=last?Math.min(now-last,100):0;last=now;elapsed+=dt;const working=tasks.filter(t=>t.state==='working');for(const task of working){task.spent+=dt;typeText(task);if(task.spent<task.duration)continue;if(phase==='design'&&task.media&&task.decodeState==='pending')continue;task.row?.classList.remove('active');closeEditor(task);if(phase==='design'&&task.media&&(task.decodeState==='failed'||failure.checked&&!failed)){failed=true;task.state='failed';task.el.dataset[mode==='section'?'state':'render']='failed';$('#media-label').textContent='키비주얼 실패 · 완료 영역 유지';canvas.dispatchEvent(new CustomEvent('demo:taskfailed',{detail:{el:task.el,name:task.name,phase}}));message('키비주얼 실패를 재현했습니다. 재시도하면 완료 영역을 유지하고 중단한 작업을 이어갑니다.','데모 실패 상황');continue;}task.state='ready';if(phase==='wireframe'){task.el.replaceChildren(...[...task.source.childNodes].map(node=>node.cloneNode(true)));task.el.classList.remove('building-block');task.el.dataset.build='ready';task.el.dataset[mode==='section'?'state':'render']='pending';}else reveal(task);canvas.dispatchEvent(new CustomEvent('demo:taskcomplete',{detail:{el:task.el,name:task.name,phase}}));message(`${task.name} ${phase==='wireframe'?'와이어프레임':'디자인'}을 반영했습니다.`,'데모 완료');}
 progress();if(tasks.some(t=>t.state==='failed')){running=false;stopFrame();$$('.message.active').forEach(el=>el.classList.remove('active'));start.disabled=false;start.textContent='실패 단계부터 재시도 ↗';pause.disabled=true;$('#status').textContent='실패 상황 · 재시도 대기';return;}
 if(tasks.every(t=>t.state==='ready')){if(phase==='wireframe'){for(const source of blueprint.querySelectorAll('[data-build-id]')){if(!canvas.querySelector(`[data-build-id="${source.dataset.buildId}"]`)){const el=mount(source);el.replaceChildren(...[...source.childNodes].map(n=>n.cloneNode(true)));}}phase='design';canvas.dataset.phase=phase;$$('[data-region]').forEach(el=>el.dataset.state=mode==='section'?'pending':'ready');$$('[data-component]').forEach(el=>el.dataset.render=mode==='component'?'pending':'ready');tasks=designTasks();message('와이어프레임 구성을 마쳤습니다. 동일한 구조에 디자인을 입힙니다.','① 완료 → ② 디자인 생성');activate();progress();moveCursors(dt);frame=requestAnimationFrame(tick);return;}running=false;stopFrame();start.disabled=false;start.textContent='다시 재생 ↗';pause.disabled=true;failure.disabled=false;$('#status').textContent='샘플 디자인 완료';canvas.dispatchEvent(new CustomEvent('demo:complete'));message('모든 영역을 표시했습니다. 커서 12개는 시각화용이며 실제 AI 에이전트 수나 품질검사 통과를 의미하지 않습니다.','시뮬레이션 종료');return;}
 activatePending();moveCursors(dt);frame=requestAnimationFrame(tick);}
function activatePending(){const capacity=mode==='section'?1:12;if(tasks.filter(t=>t.state==='working').length<capacity&&tasks.some(t=>t.state==='pending'))activate();}
function reset(){canvas.dispatchEvent(new CustomEvent('demo:reset'));$$('button[data-mode]').forEach(el=>el.setAttribute('aria-pressed',String(el.dataset.mode===mode)));stopFrame();running=false;paused=false;failed=false;last=0;elapsed=0;history.replaceChildren();canvas.replaceChildren();$$('.edit-box').forEach(el=>el.remove());phase='wireframe';canvas.dataset.phase=phase;canvas.dataset.mode=mode;$$('[data-region]').forEach(el=>{el.dataset.state=mode==='section'?'pending':'ready';el.classList.remove('reveal');});$$('[data-component]').forEach(el=>{el.dataset.render=mode==='component'?'pending':'ready';el.classList.remove('reveal');});$('#status').textContent=`${mode==='section'?'섹션별':'컴포넌트별'} · 빈 캔버스 · 시작 대기`;start.disabled=false;start.textContent='샘플 생성 시작 ↗';pause.disabled=true;pause.textContent='일시정지';failure.disabled=false;cursors.forEach(c=>c.initialized=false);tasks=wireTasks();progress();$('#mode-help').textContent=mode==='section'?'섹션 전체가 완성되면 다음 섹션으로 이동합니다. 커서 12개가 같은 섹션에서 움직입니다.':'최대 12개의 컴포넌트를 동시에 구성합니다. 커서가 담당 컴포넌트로 나뉘어 움직입니다.';message(mode==='section'?'섹션 전체를 순서대로 완성해줘.':'제목·설명·버튼·이미지·카드를 컴포넌트별로 완성해줘.','샘플 요청',true);message('빈 화면에서 와이어프레임을 먼저 생성한 뒤 디자인을 완성합니다. 12개의 스웜 커서가 작업 영역을 가리킵니다. 실제 AI 호출 없는 데모입니다.','샘플 안내');}
start.addEventListener('click',()=>{if(running)return;if(phase==='design'&&tasks.every(t=>t.state==='ready'))reset();for(const t of tasks)if(t.state==='failed'){t.state='pending';t.spent=0;}running=true;paused=false;last=0;start.disabled=true;pause.disabled=false;pause.textContent='일시정지';failure.disabled=true;tasks.filter(t=>t.state==='working').forEach(t=>t.row?.classList.add('active'));activate();swarm.hidden=false;frame=requestAnimationFrame(tick);});
pause.addEventListener('click',()=>{if(!running)return;paused=!paused;if(paused){stopFrame();$$('.message.active').forEach(el=>el.classList.remove('active'));pause.textContent='계속 재생';$('#status').textContent='샘플 재생 일시정지';message('커서와 렌더링을 함께 일시정지했습니다.','데모 일시정지');}else{last=0;pause.textContent='일시정지';tasks.filter(t=>t.state==='working').forEach(t=>t.row?.classList.add('active'));swarm.hidden=false;activate();frame=requestAnimationFrame(tick);}});
$('#reset').addEventListener('click',reset);
$$('button[data-mode]').forEach(button=>button.addEventListener('click',()=>{mode=button.dataset.mode;$$('button[data-mode]').forEach(el=>el.setAttribute('aria-pressed',String(el===button)));reset();}));
$$('button[data-view]').forEach(button=>button.addEventListener('click',()=>{canvas.dataset.view=button.dataset.view;$$('button[data-view]').forEach(el=>el.setAttribute('aria-pressed',String(el===button)));}));
document.addEventListener('visibilitychange',()=>{last=0;});reset();
